// ── STEP 1: Extract and validate the incoming payload ──────────
const body = $input.first().json;

const message    = (body.message    || '').trim();
const sessionId  = (body.session_id || 'anon').trim();
const context    = body.context     || {};
const files      = body.files       || [];

if (!message) {
  throw new Error('Empty message received');
}

// ── STEP 2: Build rich system prompt with insurance DB context ──
const categories     = (context.categories     || []).map(c => c.name).join(', ');
const relevantTypes  = (context.relevant_types || []).map(t => t.name).join(', ');
const stats          = context.stats || {};
const totalProducts  = stats.total_products  || 52;
const totalPolicies  = stats.total_policies  || 0;
const totalClients   = stats.total_clients   || 0;

const systemPrompt = `You are Ameen, an expert AI insurance broker assistant for a leading insurance brokerage in Oman. You are professional, knowledgeable, warm, and bilingual (Arabic and English).

## Your expertise covers all 52 insurance products:

### Personal Insurance:
- Motor: Comprehensive, Third Party (TPL), Classic Car, Fleet Motor
- Medical: Individual, Family, Group, Critical Illness, Dental & Optical
- Life: Term Life, Whole Life, Child Annuity, Personal Accident
- Home: Comprehensive, Fire & Allied Perils, Relocation, Plate Glass
- Travel: Individual, Family, Annual Multi-Trip, Schengen
- Domestic Worker (maid) insurance
- Yacht & watercraft

### Commercial/Corporate Insurance:
- Group Medical, Group Life, Workmen Compensation (WC)
- Property All Risk (PAR), Business Interruption
- Marine Cargo, Marine Hull, Freight Forwarder Liability
- Contractors All Risk (CAR), Erection All Risk (EAR)
- Plant & Machinery Breakdown
- Cyber Liability, Data Breach
- Professional Indemnity (PI), Medical Malpractice
- Directors & Officers (D&O) Liability
- General Third Party Liability, Product Liability
- Aviation Hull & Liability
- Surety / Performance Bonds
- Energy & Oil (upstream/downstream)
- Trade Credit Insurance
- SME Business Package

## Available categories in our system: ${categories || 'Motor, Medical, Life, Property, Marine, Engineering, Liability, Aviation, Cyber, Financial'}
${relevantTypes ? '## Relevant products for this enquiry: ' + relevantTypes : ''}

## Live statistics:
- ${totalProducts} insurance products available on website
- ${totalPolicies > 0 ? totalPolicies + ' active policies' : 'Serving hundreds of clients'}
- ${totalClients > 0 ? totalClients + ' registered clients' : 'Growing client base across Oman'}

## Operational guidelines:
1. Respond in the SAME LANGUAGE as the user (Arabic or English — detect automatically)
2. Keep responses under 220 words — be concise and actionable
3. Use bullet points and **bold** for key terms
4. Always end with a clear next step or question
5. For applications: direct users to /insurance on the website
6. For claims: direct to /my/insurance portal or call +968 2400 0000 (24/7)
7. For urgent matters: always provide the emergency hotline
8. Do NOT invent specific premium prices — explain the quote process instead
9. Be empathetic for claims situations
10. Upsell complementary products naturally (e.g., if motor → mention TPL + Comprehensive difference)

## Company info:
- Name: Ameen Hub Insurance Brokerage
- Location: Muscat, Sultanate of Oman
- License: Insurance Authority of Oman
- Emergency Claims: +968 2400 0000 (24/7)
- Portal: /my/insurance
- Apply online: /insurance`;

return [{
  json: {
    message,
    sessionId,
    context,
    files,
    systemPrompt,
    timestamp: new Date().toISOString(),
  }
}];

// ── STEP 3: Format the AI reply + generate quick replies ────────
const aiReply    = $input.first().json.message?.content || '';
const prevData   = $('Build System Prompt').first().json;
const msg        = (prevData.message || '').toLowerCase();
const sessionId  = prevData.sessionId;

if (!aiReply) {
  throw new Error('OpenAI returned empty response');
}

// ── Generate contextual quick replies ────────────────────────────
const allOptions = {
  motor:       ['Apply for Motor Insurance', 'Compare Motor Quotes', 'TPL vs Comprehensive', 'Fleet Insurance'],
  medical:     ['Individual Medical', 'Family Health Plan', 'Group Medical', 'Critical Illness'],
  life:        ['Term Life Insurance', 'Personal Accident', 'Child Annuity', 'Group Life / WC'],
  property:    ['Home Insurance', 'Commercial Property', 'Fire Insurance', 'Relocation Cover'],
  marine:      ['Marine Cargo Quote', 'Yacht Insurance', 'Hull & Machinery', 'Freight Forwarder'],
  claim:       ['How to Submit a Claim', 'Emergency Hotline', 'Track My Claim', 'Documents Required'],
  quote:       ['Motor Quote', 'Medical Quote', 'Property Quote', 'Browse All Products'],
  portal:      ['Go to My Portal', 'Track Application', 'Download Policy', 'Renew Policy'],
  arabic:      ['تأمين السيارات', 'التأمين الطبي', 'تأمين الحياة', 'عرض جميع المنتجات'],
  default:     ['🚗 Motor Insurance', '🏥 Medical Insurance', '❤️ Life Insurance', '🏠 Property Insurance'],
};

let quickReplies = allOptions.default;

if (msg.includes('motor') || msg.includes('car') || msg.includes('vehicle') || msg.includes('سيارة')) {
  quickReplies = allOptions.motor;
} else if (msg.includes('medical') || msg.includes('health') || msg.includes('طبي')) {
  quickReplies = allOptions.medical;
} else if (msg.includes('life') || msg.includes('حياة') || msg.includes('accident')) {
  quickReplies = allOptions.life;
} else if (msg.includes('property') || msg.includes('home') || msg.includes('fire') || msg.includes('منزل')) {
  quickReplies = allOptions.property;
} else if (msg.includes('marine') || msg.includes('cargo') || msg.includes('yacht') || msg.includes('بحري')) {
  quickReplies = allOptions.marine;
} else if (msg.includes('claim') || msg.includes('accident') || msg.includes('مطالبة')) {
  quickReplies = allOptions.claim;
} else if (msg.includes('quote') || msg.includes('price') || msg.includes('سعر') || msg.includes('premium')) {
  quickReplies = allOptions.quote;
} else if (msg.includes('portal') || msg.includes('status') || msg.includes('track') || msg.includes('متابعة')) {
  quickReplies = allOptions.portal;
} else if (/[\u0600-\u06ff]/.test(msg)) {
  quickReplies = allOptions.arabic;
}

return [{
  json: {
    reply: aiReply,
    quick_replies: quickReplies.slice(0, 4),
    source: 'ai',
    model: 'gpt-4o',
    session_id: sessionId,
    timestamp: new Date().toISOString(),
  }
}];
